local function getEggTimeLeft(egg)
    for _, name in ipairs({"TimeLeft","Time","Remaining","RemainingTime","Timer","HatchTime","HatchIn","Duration","Countdown","TimeRemaining"}) do
        local v = egg:GetAttribute(name)
        if typeof(v) == "number" then return v end
    end
    for _, d in ipairs(egg:GetDescendants()) do
        if (d:IsA("NumberValue") or d:IsA("IntValue")) and (d.Name:lower():find("time") or d.Name:lower():find("timer") or d.Name:lower():find("left") or d.Name:lower():find("remain")) then return d.Value end
    end
    return nil
end

local function tweenTo(pos, speed)
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp or not pos then return end
    if diamondTween then pcall(function() diamondTween:Cancel() end) end
    local dist = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
    local dur = math.max(dist / math.max(speed, 1), 0.15)
    diamondTween = TweenService:Create(hrp, TweenInfo.new(dur, Enum.EasingStyle.Linear), { CFrame = CFrame.new(Vector3.new(pos.X, pos.Y, pos.Z)) })
    diamondTween:Play()
    diamondTween.Completed:Wait()
end

local function collectEggGemDrops()
    local drops = workspace:FindFirstChild("EggGemDrops")
    if not drops then return end
    while diamondOn and drops.Parent and #drops:GetChildren() > 0 do
        for _, child in ipairs(drops:GetChildren()) do
            if not diamondOn then return end
            if not child.Parent then continue end
            local pos = nil
            if child:IsA("BasePart") then pos = child.Position else pos = getBasePos(child) end
            if not pos then continue end
            pcall(function() tweenTo(Vector3.new(pos.X, pos.Y + 1, pos.Z), diamondFarmSpeed) end)
            task.wait(0.1)
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local part = nil
            if child:IsA("BasePart") then part = child
            elseif child:IsA("Model") then part = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart") end
            if hrp and part then pcall(function() firetouchinterest(hrp, part, 0) task.wait(0.05) firetouchinterest(hrp, part, 1) end) end
        end
        task.wait(0.1)
    end
end

local function diamondFarmLoop()
    while diamondOn do
        if hasGemDrops() then
            collectEggGemDrops()
        else
            if not diamondZone then task.wait(0.5) continue end
            local eggs = getEggsInZone(diamondZone)
            if #eggs == 0 then task.wait(1) continue end
            for _, egg in ipairs(eggs) do
                if not diamondOn then break end
                if hasGemDrops() then break end
                local pos, base = getOffsetPos(egg)
                if not pos then continue end
                pcall(function()
                    walkDirect(pos, base, false)
                    equipPickaxe()
                    while diamondOn and egg.Parent do
                        if hasGemDrops() then break end
                        local h = getEggHealth(egg)
                        if h ~= nil and h <= 0 then break end
                        local t = getEggTimeLeft(egg)
                        if t ~= nil and t <= 0 then break end
                        task.wait(0.15)
                    end
                end)
            end
        end
        task.wait(0.2)
    end
end

-- ================= ANTI RAGDOLL AUTO DETECT =================
local autoRagdollOn = false
local ragdollWatchConn = nil
local lastY = 0
local lastSafeCF = nil
local protecting = false

local function stopAutoRagdoll()
    if ragdollWatchConn then pcall(function() ragdollWatchConn:Disconnect() end) ragdollWatchConn = nil end
    protecting = false
    lastSafeCF = nil
    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function()
        hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true)
        hum.PlatformStand = false
    end) end
end

local function startAutoRagdoll()
    stopAutoRagdoll()
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then lastY = hrp.Position.Y lastSafeCF = hrp.CFrame end
    ragdollWatchConn = RunService.Heartbeat:Connect(function()
        if not autoRagdollOn then return end
        local c = plr.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if not hum or not r then return end
        local curY = r.Position.Y
        local deltaY = curY - lastY
        local velY = r.AssemblyLinearVelocity.Y
        if not protecting and hum.FloorMaterial ~= Enum.Material.Air and velY < 5 and math.abs(deltaY) < 0.5 then
            lastSafeCF = r.CFrame
            lastY = curY
            return
        end
        if not protecting and deltaY >= 2 then
            protecting = true
            if lastSafeCF then r.CFrame = CFrame.new(lastSafeCF.Position + Vector3.new(0, 0.5, 0)) * (lastSafeCF - lastSafeCF.Position)
            else r.CFrame = CFrame.new(r.Position.X, lastY, r.Position.Z) end
            r.AssemblyLinearVelocity = Vector3.zero
            r.AssemblyAngularVelocity = Vector3.zero
            r.Velocity = Vector3.zero
            hum.PlatformStand = false
            hum:ChangeState(Enum.HumanoidStateType.RunningNoPhysics)
            task.wait()
            hum:ChangeState(Enum.HumanoidStateType.Running)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
            task.delay(0.8, function()
                if hum.Parent then
                    hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
                    hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                    hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true)
                end
                protecting = false
                local rr = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if rr then lastY = rr.Position.Y lastSafeCF = rr.CFrame end
            end)
            return
        end
        if protecting and (hum:GetState() == Enum.HumanoidStateType.Ragdoll or hum:GetState() == Enum.HumanoidStateType.FallingDown or hum.PlatformStand) then
            hum.PlatformStand = false
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end
        if not protecting and deltaY < 2 then lastY = curY end
    end)
end

